package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var reader = bufio.NewReader(os.Stdin)

func readLine() string {
	line, _ := reader.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
}

func readInt() int {
	n, _ := strconv.Atoi(readLine())
	return n
}

func readLong() int64 {
	n, _ := strconv.ParseInt(readLine(), 10, 64)
	return n
}

func readInts() []int {
	parts := strings.Split(readLine(), " ")
	res := make([]int, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.Atoi(p)
	}
	return res
}

func readLongs() []int64 {
	parts := strings.Split(readLine(), " ")
	res := make([]int64, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.ParseInt(p, 10, 64)
	}
	return res
}

func main() {
	n := readInt()
	fmt.Print(3 * n / 2)
}
